"""Request pre-flight for the Copilot v2 chat route (host side).

A pre-flight inspects an already-parsed :class:`RunRequest` *before* the agent
loop is entered and may short-circuit the run. This module implements the
guardrails pre-flight: it reuses the v1 :class:`GuardrailsPolicyChecker`
unchanged, and on a violation streams a CUSTOM AG-UI event plus persists the
turn so the outcome survives a reload.

The pre-flight deliberately lives in the host layer, not in
``rasa.builder.copilot.pydantic_ai``. Which provider moderates content, what
counts as a violation, and the Hello-Rasa user/project identity that scopes it
are all deployment choices; the Copilot v2 runtime stays free of them and a
different host may supply another pre-flight, or none. Every guardrails and
Lakera symbol this slice needs is imported here and nowhere in the runtime
package.
"""

from __future__ import annotations

import uuid
from collections.abc import AsyncIterator
from dataclasses import dataclass, replace
from typing import TYPE_CHECKING, Any, Optional, Protocol

import structlog

from rasa.builder.config import (
    GUARDRAILS_ENABLE_BLOCKING,
    HELLO_RASA_PROJECT_ID,
    LAKERA_COPILOT_HISTORY_GUARDRAIL_PROJECT_ID,
)
from rasa.builder.copilot.constants import ROLE_ASSISTANT, ROLE_COPILOT, ROLE_USER
from rasa.builder.copilot.models import (
    ChatMessage,
    CopilotChatMessage,
    CopilotContext,
    GuardrailBlockedContent,
    GuardrailPolicyViolationContent,
    ResponseCategory,
    TextContent,
    UserChatMessage,
)
from rasa.builder.copilot.pydantic_ai import ag_ui_events
from rasa.builder.copilot.pydantic_ai.api import encode_sse_event
from rasa.builder.copilot.pydantic_ai.persisted_messages import (
    rows_for_text_turn,
    trailing_user_text,
)
from rasa.builder.copilot.pydantic_ai.types import RunRequest
from rasa.builder.copilot.response_handling.base_copilot_response_handler import (
    BaseCopilotResponseHandler,
)
from rasa.builder.guardrails.constants import (
    BLOCK_SCOPE_PROJECT,
    BLOCK_SCOPE_USER,
    BlockScope,
)
from rasa.builder.guardrails.store import guardrails_store

if TYPE_CHECKING:
    from rasa.builder.copilot.pydantic_ai.thread_store import ThreadStore
    from rasa.builder.guardrails.policy_checker import GuardrailsPolicyChecker

structlogger = structlog.get_logger()

# Name of the CUSTOM AG-UI event that carries a short-circuited run's outcome.
# Host vocabulary: the frontend keys its violation variant on this name, and the
# runtime never learns it.
POLICY_VIOLATION_EVENT = "policy_violation"


@dataclass(frozen=True)
class PreflightViolation:
    """A pre-flight verdict that ends the run before the agent loop.

    ``content`` is the templated, user-facing text — never the message that
    triggered it, and never provider detection metadata. ``category`` carries
    the v1 response-category vocabulary so both transports describe a violation
    the same way.
    """

    content: str
    category: str


@dataclass(frozen=True)
class PreflightOutcome:
    """What a pre-flight decided about one request.

    ``run_request`` is the request the runtime should execute; a pre-flight may
    return it modified (for guardrails: with earlier flagged turns stripped).
    ``violation`` is set only when the run must not proceed.
    """

    run_request: RunRequest
    violation: Optional[PreflightViolation] = None


@dataclass(frozen=True)
class _AdaptedRequest:
    """AG-UI messages restated in the shape the v1 policy checker consumes.

    ``messages`` holds the very objects the checker annotates in place, kept
    separately because the checker rebinds ``context.copilot_chat_history`` to a
    filtered list. ``positions`` maps each adapted message back to its index in
    the original request.
    """

    context: CopilotContext
    messages: list[ChatMessage]
    positions: list[int]


class RequestPreflight(Protocol):
    """Callable contract for a route-layer pre-flight.

    Implementations must be side-effect-safe for the clean path: returning an
    unchanged :class:`PreflightOutcome` has to leave the run exactly as it would
    have been without the pre-flight.
    """

    async def __call__(
        self, run_request: RunRequest, *, user_id: str
    ) -> PreflightOutcome:
        """Inspect the request and decide whether the agent loop may run."""
        ...


def guardrails_preflight(
    checker: Optional["GuardrailsPolicyChecker"],
) -> RequestPreflight:
    """Bind a policy checker into a route-ready pre-flight.

    The route composes pre-flights, so each is reduced to the same
    ``(run_request, user_id)`` contract with its own dependencies closed over —
    which is how a second pre-flight can be added beside this one, and how a host
    without guardrails supplies a different one or none at all.

    Args:
        checker: The policy checker, or ``None`` when guardrails are disabled.

    Returns:
        The pre-flight to run for this request.
    """

    async def preflight(run_request: RunRequest, *, user_id: str) -> PreflightOutcome:
        return await run_guardrails_preflight(
            run_request, user_id=user_id, checker=checker
        )

    return preflight


async def run_guardrails_preflight(
    run_request: RunRequest,
    *,
    user_id: str,
    checker: Optional["GuardrailsPolicyChecker"],
) -> PreflightOutcome:
    """Screen a Copilot v2 request against the guardrails policy.

    Mirrors the v1 ``/copilot`` sequence: block-scope gate first, then a policy
    check over the user messages in the request. A flagged latest user message
    short-circuits the run; earlier flagged turns are stripped from the request
    instead, so the agent never sees content the policy rejected.

    Args:
        run_request: The parsed AG-UI request for this run.
        user_id: Hello-Rasa user id that scopes strikes and blocks.
        checker: The policy checker, or ``None`` when guardrails are disabled.

    Returns:
        The outcome to act on. A ``None`` violation means the run proceeds with
        ``outcome.run_request``.
    """
    # Guardrails off: nothing to check, and the block store can only hold
    # strikes that a check recorded, so the block gate has nothing to find.
    if checker is None:
        return PreflightOutcome(run_request)

    if (scope := await _block_scope(user_id)) is not None:
        return PreflightOutcome(run_request, _blocked_violation(scope))

    adapted = _adapt_request(run_request)
    try:
        violation_content = await checker.check_copilot_chat_for_policy_violations(
            context=adapted.context,
            hello_rasa_user_id=user_id,
            hello_rasa_project_id=HELLO_RASA_PROJECT_ID,
            lakera_project_id=LAKERA_COPILOT_HISTORY_GUARDRAIL_PROJECT_ID,
        )
    except Exception as exc:
        # Fail open, as v1 does for a provider error: a guardrails outage must
        # not take the copilot down with it.
        structlogger.warning(
            "copilot_v2.preflight.check_failed",
            thread_id=run_request.thread_id,
            error=str(exc),
        )
        return PreflightOutcome(run_request)

    if violation_content is not None:
        violation = await _record_violation_and_maybe_block(violation_content, user_id)
        structlogger.info(
            "copilot_v2.preflight.violation_detected",
            thread_id=run_request.thread_id,
            category=violation.category,
        )
        return PreflightOutcome(run_request, violation)

    return PreflightOutcome(_sanitized(run_request, adapted))


async def stream_violation_sse(
    violation: PreflightViolation,
    run_request: RunRequest,
    *,
    thread_store: Optional["ThreadStore"] = None,
) -> AsyncIterator[str]:
    """Stream the SSE frames for a run the pre-flight refused, persisting it.

    Emits a complete, bracketed run — ``RUN_STARTED``, the CUSTOM violation
    event, ``RUN_FINISHED`` — so the client's run state machine needs no special
    case for a short-circuit. Persistence happens first and best-effort: the
    streamed ``messageId`` then names a row the history endpoint can return, and
    a storage failure still lets the user see the response.

    Args:
        violation: The pre-flight verdict to surface.
        run_request: The request that was refused.
        thread_store: Where to persist the turn, or ``None`` to skip.

    Yields:
        Encoded SSE frames, ready to write to the response stream.
    """
    message_id = f"msg-{uuid.uuid4().hex}"
    if thread_store is not None:
        await _persist_violation(thread_store, run_request, violation, message_id)

    yield encode_sse_event(
        ag_ui_events.run_started(run_request.thread_id, run_request.run_id)
    )
    yield encode_sse_event(
        ag_ui_events.custom(
            POLICY_VIOLATION_EVENT,
            {
                "content": violation.content,
                "category": violation.category,
                "messageId": message_id,
            },
        )
    )
    yield encode_sse_event(
        ag_ui_events.run_finished(run_request.thread_id, run_request.run_id)
    )


def violation_rows(
    run_request: RunRequest,
    violation: PreflightViolation,
    message_id: str,
) -> list[dict[str, Any]]:
    """Build the AG-UI rows that record a refused turn.

    The user row matches what the end-of-run persist hook would have written for
    a completed turn, so a thread reads the same whether or not the run was
    refused. The violation row is an assistant row plus a response-category
    marker, which is what the client renders the violation variant from on
    reload.
    """
    return rows_for_text_turn(
        user_text=trailing_user_text(run_request.messages),
        assistant_text=violation.content,
        response_category=violation.category,
        assistant_message_id=message_id,
    )


async def _persist_violation(
    thread_store: "ThreadStore",
    run_request: RunRequest,
    violation: PreflightViolation,
    message_id: str,
) -> None:
    """Append the refused turn to the thread store, swallowing failures."""
    try:
        await thread_store.append_messages(
            run_request.thread_id,
            violation_rows(run_request, violation, message_id),
        )
    except Exception as exc:
        structlogger.warning(
            "copilot_v2.preflight.persist_failed",
            thread_id=run_request.thread_id,
            error=str(exc),
        )


async def _block_scope(user_id: str) -> Optional[BlockScope]:
    """Return the scope this user is currently blocked at, if blocking is on."""
    if not GUARDRAILS_ENABLE_BLOCKING:
        return None
    return await guardrails_store.check_block_scope(user_id)


async def _record_violation_and_maybe_block(
    violation_content: GuardrailPolicyViolationContent,
    user_id: str,
) -> PreflightViolation:
    """Record a strike and escalate to a block once a threshold is crossed."""
    if not GUARDRAILS_ENABLE_BLOCKING:
        return _as_violation(violation_content)

    result = await guardrails_store.record_violation(user_id)
    if result.user_blocked_now:
        return _blocked_violation(BLOCK_SCOPE_USER)
    if result.project_blocked_now:
        return _blocked_violation(BLOCK_SCOPE_PROJECT)
    return _as_violation(violation_content)


def _blocked_violation(scope: BlockScope) -> PreflightViolation:
    """Build the violation for a user or project that is currently blocked."""
    return _as_violation(BaseCopilotResponseHandler.respond_to_guardrail_blocked(scope))


def _as_violation(
    content: GuardrailPolicyViolationContent | GuardrailBlockedContent,
) -> PreflightViolation:
    """Narrow a v1 generated-content model to the transport-neutral verdict."""
    return PreflightViolation(
        content=content.content,
        category=content.response_category.value,
    )


def _adapt_request(run_request: RunRequest) -> _AdaptedRequest:
    """Adapt AG-UI messages to the chat history the v1 checker expects.

    Only the roles the checker reasons about are adapted, so each adapted
    message is paired with its index in ``run_request.messages``. That pairing is
    how a flagged message is traced back to the request without the checker
    having to learn the AG-UI shape.
    """
    history: list[ChatMessage] = []
    positions: list[int] = []
    for position, message in enumerate(run_request.messages):
        if message.role == ROLE_USER:
            history.append(
                UserChatMessage(
                    content=[TextContent(type="text", text=message.content)]
                )
            )
        elif message.role == ROLE_ASSISTANT:
            history.append(
                CopilotChatMessage(
                    role=ROLE_COPILOT,
                    content=[TextContent(type="text", text=message.content)],
                )
            )
        else:
            continue
        positions.append(position)

    return _AdaptedRequest(
        context=CopilotContext(copilot_chat_history=history),
        messages=history,
        positions=positions,
    )


def _sanitized(run_request: RunRequest, adapted: _AdaptedRequest) -> RunRequest:
    """Drop earlier flagged turns from the request the runtime will execute.

    The checker annotates each flagged user message in place. Removing the
    flagged message alone would leave the reply that answered it, so the whole
    exchange goes: the user message plus every copilot row up to the next user
    turn. One v2 assistant turn can persist as several rows — text split around
    a tool call resends as consecutive copilot messages — so the reply is a run
    of rows, not a single one.
    """
    history = adapted.messages
    dropped: set[int] = set()
    for index, message in enumerate(history):
        if message.response_category != ResponseCategory.GUARDRAILS_POLICY_VIOLATION:
            continue
        dropped.add(adapted.positions[index])
        following = index + 1
        while following < len(history) and history[following].role == ROLE_COPILOT:
            dropped.add(adapted.positions[following])
            following += 1

    if not dropped:
        return run_request

    structlogger.info(
        "copilot_v2.preflight.request_sanitized",
        thread_id=run_request.thread_id,
        dropped_messages=len(dropped),
        kept_messages=len(run_request.messages) - len(dropped),
    )
    return replace(
        run_request,
        messages=tuple(
            message
            for position, message in enumerate(run_request.messages)
            if position not in dropped
        ),
    )
